 const refreshStrip=(name,id,cls)=>{const vals=[...document.querySelectorAll(`input[name="${name}"]:checked`)].map(x=>x.value);document.querySelectorAll(`input[name="${name}"]`).forEach(i=>i.closest('label')?.classList.toggle('selected',i.checked));const box=document.getElementById(id);if(box)box.innerHTML=`Selected (${vals.length}): ${vals.map(x=>`<span class="selected-chip">${esc(x)}${cls?' <button type="button" data-remove="'+esc(x)+'">×</button>':''}</span>`).join('')||'<span>None selected.</span>'}`;box?.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const input=[...document.querySelectorAll(`input[name="${name}"]`)].find(x=>x.value===b.dataset.remove);if(input){input.checked=false;refreshStrip(name,id,cls)}})};
 document.querySelectorAll('input[name="campaign-objective"]').forEach(x=>x.onchange=()=>refreshStrip('campaign-objective','ci-selected-objectives',true));
 document.querySelectorAll('input[name="brand-personality"]').forEach(x=>x.onchange=()=>refreshStrip('brand-personality','ci-selected-personality',false));
