 document.getElementById('ci-add-message').onclick=()=>{const wrap=document.getElementById('ci-messages');if(wrap.children.length>=5){toast('Up to 5 key messages.','info');return}const row=document.createElement('div');row.className='message-row';row.innerHTML='<input data-key-message placeholder="Enter key brand message"><button type="button" class="remove-message-btn">×</button>';row.querySelector('button').onclick=()=>row.remove();wrap.appendChild(row)};
 const collect=()=>({goal:document.getElementById('ci-goal').value,objective:document.getElementById('ci-goal').value,objectives:[...document.querySelectorAll('input[name="campaign-objective"]:checked')].map(x=>x.value),market:document.getElementById('ci-market').value.trim(),category:document.getElementById('ci-category').value.trim(),subcategory:document.getElementById('ci-subcategory').value.trim(),campaignType:document.getElementById('ci-type').value,currency:document.getElementById('ci-currency').value,budget:num(document.getElementById('ci-budget').value),startDate:document.getElementById('ci-start').value,endDate:document.getElementById('ci-end').value,brandName:document.getElementById('ci-brand-name').value.trim(),brand:document.getElementById('ci-brand-name').value.trim(),brandPositioning:document.getElementById('ci-positioning').value.trim(),brandPromise:document.getElementById('ci-promise').value.trim(),brandPersonalities:[...document.querySelectorAll('input[name="brand-personality"]:checked')].map(x=>x.value),brandPersonality:[...document.querySelectorAll('input[name="brand-personality"]:checked')].map(x=>x.value),brandValues:(document.getElementById('ci-brand-values')?.value||'').split(/[\n,]/).map(x=>x.trim()).filter(Boolean),brandValuesText:document.getElementById('ci-brand-values')?.value.trim()||'',brandAvoid:(document.getElementById('ci-brand-avoid')?.value||'').split(/[\n,]/).map(x=>x.trim()).filter(Boolean),brandAvoidText:document.getElementById('ci-brand-avoid')?.value.trim()||'',keyMessages:[...document.querySelectorAll('[data-key-message]')].map(x=>x.value.trim()).filter(Boolean)});
 const save=async(e,continueNext)=>{e?.preventDefault();const name=document.getElementById('ci-name').value.trim(),payload=collect();if(!name){toast('Enter a campaign name before saving.','error');return}if(continueNext&&(!payload.goal||!payload.objectives.length||payload.budget==null||!payload.market||!payload.brandName||!payload.brandPositioning||!payload.keyMessages.length)){toast('Please complete the required campaign fields.','error');return}if(payload.startDate&&payload.endDate&&payload.endDate<payload.startDate){toast('End date must be after the start date.','error');return}const buttons=[document.getElementById('ci-draft'),document.querySelector('#campaign-intake-form button[type="submit"]')];buttons.forEach(b=>{if(b){b.disabled=true;b.textContent='Processing…'}});try{let q=S.selectedCampaign?.id?await sb.from('campaigns').update({name,payload,status:'draft',updated_at:new Date().toISOString()}).eq('id',S.selectedCampaign.id).select().single():await sb.from('campaigns').insert({organization_id:S.org.id,name,payload,status:'draft',created_by:S.session.user.id}).select().single();if(q.error)throw q.error;await refresh();S.selectedCampaign=q.data;toast(continueNext?'Campaign saved':'Draft saved','good');if(continueNext){S.page=1;renderPage()}else renderPage()}catch(err){toast(err.message||'Could not save campaign','error')}finally{buttons.forEach(b=>{if(b){b.disabled=false}})}};
 document.getElementById('campaign-intake-form').onsubmit=e=>save(e,true);document.getElementById('ci-draft').onclick=e=>save(e,false);
