function renderBatch(){const el=document.getElementById('creator-batch-list');if(!el)return;el.innerHTML=S.creatorBatch.map((x,i)=>`<div class="list-card"><div><b>${esc(x.name)}</b><small>${esc(x.channel||'—')} · ${money(x.followers||0)} followers${x.secondaryChannel?' · '+esc(x.secondaryChannel):''}</small></div><button class="btn danger" type="button" data-remove-batch="${i}">Remove</button></div>`).join('')||'<div class="empty">No creators waiting in the batch.</div>';el.querySelectorAll('[data-remove-batch]').forEach(b=>b.onclick=()=>{S.creatorBatch.splice(Number(b.dataset.removeBatch),1);renderBatch()})}
function creators(c){c.innerHTML=`<div class="hero"><div><div class="kicker">KOL PERSONA / CREATOR INTELLIGENCE</div><h2>Add creators you are considering</h2><p>Enter what is known today. The system calculates Audience Fit, Content Fit, Brand Alignment, Performance Evidence and Risk after analysis.</p></div><div class="hero-actions"><span class="pill cyan">Up to 100 creators / batch</span></div></div><section class="card"><div class="section-head"><div><div class="label">Creator intake</div><h2>Creator profile</h2><p class="sub">Some creators may be new to the brand. Unknown fields stay unknown until the system has evidence.</p></div></div><form id="creator-form"><div class="form-grid"><div class="field"><label>Creator / KOL Name <span class="required-star">*</span></label><input id="cr-name" required placeholder="Creator name"></div><div class="field"><label>Primary Channel <span class="required-star">*</span></label><select id="cr-channel" required><option value="">Select channel</option><option>Instagram</option><option>TikTok</option><option>YouTube</option><option>Facebook</option><option>X</option><option>Weibo</option><option>Other</option></select></div><div class="field"><label>Secondary Channel</label><select id="cr-secondary"><option value="">None / not known</option><option>Instagram</option><option>TikTok</option><option>YouTube</option><option>Facebook</option><option>X</option><option>Weibo</option><option>Other</option></select></div><div class="field"><label>Followers</label><input id="cr-followers" type="number" min="0" placeholder="e.g. 850000"></div><div class="field"><label>Engagement rate %</label><input id="cr-er" type="number" min="0" max="100" step="0.01" placeholder="Optional if unknown"></div><div class="field"><label>Rate / Fee</label><input id="cr-rate" type="number" min="0" placeholder="Optional"></div><div class="field"><label>Profile link</label><input id="cr-profile" type="url" placeholder="https://..."></div><div class="field"><label>Creator photo URL</label><input id="cr-photo" type="url" placeholder="Optional direct image URL"><span class="hint">If supplied, the analysis result will show the creator photo. Profile links are also used for the profile action.</span></div></div><div style="margin-top:22px"><div class="label">Creator intelligence signals</div><div class="signal-grid" style="margin-top:10px">${Object.keys(signalExamples).map(k=>chipGroup(k,[])).join('')}</div><div class="hint" style="margin-top:10px">Every category has an Other field so the analyst can add signals that are not in the examples.</div></div><div class="actions"><button class="btn" type="button" id="add-creator-batch">+ Add to batch</button><button class="btn primary" type="button" id="save-creator-batch">Save ${S.creatorBatch.length?'batch ('+S.creatorBatch.length+')':'batch'}</button></div></form></section><section class="card" style="margin-top:14px"><div class="section-head"><div><div class="label">Batch queue</div><h2>Creators ready to save</h2></div><span class="pill">${S.creatorBatch.length}/100</span></div><div id="creator-batch-list"></div></section><section class="card" style="margin-top:14px"><div class="section-head"><div><div class="label">Creator registry</div><h2>${S.creators.length} creators saved</h2></div></div>${S.creators.length?`<div class="table-wrap"><table><thead><tr><th>Creator</th><th>Primary</th><th>Secondary</th><th>Followers</th><th>ER</th><th>Profile</th></tr></thead><tbody>${S.creators.map(x=>{const p=x.payload||{};return `<tr><td><b>${esc(x.name)}</b></td><td>${esc(p.channel||'—')}</td><td>${esc(p.secondaryChannel||'—')}</td><td>${money(p.followers)}</td><td>${p.er==null?'—':pct(p.er)}</td><td>${p.profileUrl?`<a href="${esc(p.profileUrl)}" target="_blank" rel="noopener">Open</a>`:'—'}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">No creators saved yet.</div>'}</section>`;renderBatch();const selected={};document.querySelectorAll('[data-chip]').forEach(b=>b.onclick=()=>{const k=b.dataset.chip;document.querySelectorAll(`[data-chip="${k}"]`).forEach(x=>x.classList.remove('selected'));b.classList.add('selected');});document.getElementById('add-creator-batch').onclick=()=>{if(S.creatorBatch.length>=100){toast('Maximum 100 creators per batch.','error');return}const x=creatorFormCollect();if(!x.name||!x.channel){toast('Creator name and primary channel are required.','error');return}if(Object.values(x.intelligence).some(v=>!v.length)){toast('Add at least one intelligence signal in every category.','error');return}S.creatorBatch.push(x);toast(`${x.name} added to batch`,'good');document.getElementById('creator-form').reset();document.querySelectorAll('[data-chip]').forEach(b=>b.classList.remove('selected'));document.querySelectorAll('.signal-other').forEach(i=>i.value='');document.getElementById('save-creator-batch').textContent=`Save batch (${S.creatorBatch.length})`;renderBatch()};document.getElementById('save-creator-batch').onclick=async()=>{if(!S.creatorBatch.length){const x=creatorFormCollect();if(x.name&&x.channel){S.creatorBatch.push(x)}else{toast('Add at least one creator first.','error');return}}const btn=document.getElementById('save-creator-batch');btn.disabled=true;btn.textContent='Processing…';try{for(const x of S.creatorBatch){const payload={channel:x.channel,secondaryChannel:x.secondaryChannel,followers:x.followers,er:x.er,rate:x.rate,profileUrl:x.profileUrl,profileImageUrl:x.profileImageUrl,intelligence:x.intelligence};const q=await sb.from('creators').insert({organization_id:S.org.id,name:x.name,payload}).select().single();if(q.error)throw q.error}S.creatorBatch=[];await refresh();toast('Creator batch saved','good');renderPage()}catch(err){toast(err.message||'Could not save creator batch','error')}finally{btn.disabled=false;btn.textContent='Save batch'}}}
function latestDecisionRows(){const map=new Map();S.decisions.filter(x=>!S.selectedCampaign||x.campaign_id===S.selectedCampaign.id).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).forEach(d=>{if(d.creator_id&&!map.has(d.creator_id))map.set(d.creator_id,d)});return [...map.values()].map(d=>({decision:d,creator:S.creators.find(c=>c.id===d.creator_id)})).filter(x=>x.creator)}
