  const ids=S.creators.length<=100&&!checked.length?S.creators.map(x=>x.id):checked;
  if(!ids.length){toast('Select up to 100 creators for this analysis run.','error');return}
  if(ids.length>100){toast('A maximum of 100 creators can be analyzed per run.','error');return}
